def backspaceCompare(S: str, T: str) -> bool:
    def next_valid_char_index(s, i):
        backspace = 0
        while i >= 0:
            if s[i] == '#':
                backspace += 1
                i -= 1
            elif backspace > 0:
                backspace -= 1
                i -= 1
            else:
                break
        return i

    i, j = len(S) - 1, len(T) - 1
    while i >= 0 or j >= 0:
        i = next_valid_char_index(S, i)
        j = next_valid_char_index(T, j)
        if i >= 0 and j >= 0:
            if S[i] != T[j]:
                return False
        elif i >= 0 or j >= 0:
            # One string has characters left and the other doesn't
            return False
        i -= 1
        j -= 1
    return True
